            var ci = [M.CI0], path = [M.CI0], o5 = [null], p = [M.P0], fl = [M.FLOOR], md = [M.MODAL0];
            for (var i = 0; i < h.length; i++) {
                ci.push(h[i].CI); path.push(Math.round(SMModel.pathCI(h[i].t) * 100) / 100); o5.push(h[i].CI5);
                p.push(h[i].P); fl.push(M.FLOOR); md.push(h[i].modal);
            }
            return {
                ciChart: { labels: labels, datasets: [{ data: ci }, { data: path }, { data: o5 }] },
                pChart: { labels: labels, datasets: [{ data: p }, { data: fl }, { data: md }] }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.chargeInForce', label: 'Charge', i18nKey: 'col_charge', formatter: function (v) { return self._usd(v); } },
                { key: 'results.congestionIndex', label: 'Congestion', i18nKey: 'col_ci', formatter: function (v) { return self._ci(v); } },
                { key: 'results.pm25VsWho', label: 'PM2.5 vs WHO', i18nKey: 'col_aq', formatter: function (v) { return self._pct(v); } },
                { key: 'results.durability', label: 'Durability', i18nKey: 'col_p', formatter: function (v) { return self._num(v, 0); } },
                { key: 'results.transitShare', label: 'Transit share', i18nKey: 'col_modal', formatter: function (v) { return self._pct(v); } },
                { key: 'results.carsPerThousand', label: 'Cars per 1,000', i18nKey: 'col_cars' },
                { key: 'results.outlook5y', label: 'Five-year outlook', i18nKey: 'col_ci5', formatter: function (v) { return self._ci(v); } },
                { key: 'results.envelopeLeft', label: 'Envelope left', i18nKey: 'col_env', formatter: function (v) { return self._usdM(v); } },
                { key: 'results.overallScore', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint() { return null; }
        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var last = history[history.length - 1] || {};
            var st = this._state();
            var ds = last.domainState || (st && st.domainState) || {};
            var perf = ds.performance || {};
            var s = typeof perf.overallScore === 'number' ? perf.overallScore : 0;
            var tier = perf.tier || SMModel.tier(s);
            var a = this._analyse(ds);
            var lr = last.results || {};
            return {
                totalPeriods: history.length,
                overallScore: s, composite: s, totalScore: s, score: s,
                outcomeScore: perf.outcome, processScore: perf.process,
                performance: tier, performanceKey: tier, performanceLabel: this._t('perf_' + tier),
                insights: a.insights, turningPoint: a.turning,
                finalCongestionIndex: lr.congestionIndex, finalPm25VsWho: lr.pm25VsWho, finalDurability: lr.durability, outlook5y: lr.outlook5y
            };
        }

        formatCompletionMessage(summary) {
            var st = this._state();
            var ds = (st && st.domainState) || {};
            return this._debriefHTML(ds, summary || {});
        }

        /* ---------- reading a run ---------- */
        _flags(ds) {
            var h = ds.hist || [], f = { lanes: [], newlane: 0, brt: 0, rebate: false, city: 0, suspend: 0, halve: 0, forced: ds.forcedAt || 0,
                oneoff: false, integrated: false, single: false, six: false, dismiss: false, confirm: false, over: ds.overspend || 0, noAlt: 0, noAltR: 0,
                flips: [], strike: false, order: !!ds.orderFired, charge: 0 };
            for (var i = 0; i < h.length; i++) {
                var r = h[i];
                if (r.lane !== 'none') { f.lanes.push(r.t); }
                if (r.lane === 'newlane' && !f.newlane) { f.newlane = r.t; }
                if (r.t >= 2 && r.chIn === 0 && r.zoning === 'none' && r.transit >= 7) { f.brt++; }
                if (r.zoning === 'citywide') { f.city++; }
                if (r.t === 1) { f.single = r.reading === 'single'; f.six = r.reading === 'six'; }
                if (r.t === 2 && r.reading === 'rebate') { f.rebate = true; }
                if (r.t === 3) { f.dismiss = r.reading === 'dismiss'; f.confirm = r.reading === 'confirm'; f.strike = !!r.strike; }
                if (r.t === 4 && r.reading === 'suspend') { f.suspend = 4; }
                if (r.t === 4 && r.reading === 'halve') { f.halve = 4; }
                if (r.t === 5) { f.oneoff = r.reading === 'oneoff'; f.integrated = r.reading === 'integrated'; }
                if (r.noAlt >= 1.6 && r.parts.charge <= -8 && !f.noAlt) { f.noAlt = r.t; f.noAltR = r.parts.charge; }
                if (i && h[i - 1].charge - r.charge >= 2.5) { f.flips.push(r.t); }
                if (r.chIn > f.charge) { f.charge = r.chIn; }
            }
            return f;
        }

        _cause(r, prev, h) {
            if (r.forced) { return this._t('cause_forced', { p: this._num(r.P, 0) }); }
            if (r.t === 4 && r.reading === 'suspend') { return this._t('cause_suspend'); }
            if (r.strike) { return this._t('cause_strike'); }
            if (r.t === 4 && r.works > 0.3) { return this._t('cause_dip', { w: this._pct(3.5 * Math.min(1.2, r.works), 1) }); }
            if (r.noAlt >= 1.6 && r.parts.charge <= -8) { return this._t('cause_noalt', { c: this._usd(r.chIn) }); }
            if (r.over > 0) { return this._t('cause_over', { o: this._usdM(r.over) }); }
            /* a lane fills only after it has opened (built in round n, open from n+1, filling from n+2), and only when
               no stoppage, works, unbuffered charge or overspend explains the round better */
            var lt = 0;
            for (var li = 0; h && li < h.length && h[li].t < r.t - 1; li++) { if (h[li].lane === 'newlane') { lt = h[li].t; break; } }
            if (lt && r.dCI > 0.05 && h[lt]) { return this._t('cause_lanefill', { a: this._ci(h[lt].CI), b: this._ci(r.CI) }); }
            if (r.dCI > 0.05) { return this._t('cause_ci', { a: this._ci(r.CI - r.dCI), b: this._ci(r.CI) }); }
            return this._t('cause_p', { d: this._sign(r.dP, 1) });
        }

        _analyse(ds) {
            var self = this, h = ds.hist || [], f = this._flags(ds), ins = [], qs = [];
            if (!h.length) { return { insights: [], turning: '', questions: [] }; }
            var last = h[h.length - 1], first = h[0];
            var sh = ds.scoreHistory || [];
            var worst = 0, wt = 0;
            for (var i = 1; i < sh.length; i++) { var dl = sh[i] - sh[i - 1]; if (dl < worst) { worst = dl; wt = i + 1; } }
            var turning;
            if (wt && worst <= -6) {
                turning = this._t('tp_round', { t: wt, a: sh[wt - 2], b: sh[wt - 1], cause: this._cause(h[wt - 1], h[wt - 2], h), c: sh[sh.length - 1] });
            } else {
                var hardT = 1, hardD = 999;
                for (var j = 1; j < sh.length; j++) { var dj = sh[j] - sh[j - 1]; if (dj < hardD) { hardD = dj; hardT = j + 1; } }
                if (sh.length < 2 || hardD >= 0) { turning = this._t('tp_none', { c: sh[sh.length - 1] }); }
                else { turning = this._t('tp_steady', { t: hardT, ev: this._t('ev_' + hardT), a: sh[hardT - 2], b: sh[hardT - 1], c: sh[sh.length - 1] }); }
            }
            /* mistakes first, each in its own words */
            if (f.newlane) {
                /* say "filled" only when it did: the city ends no better than the round before the lane opened */
                var lr = h[f.newlane], pre = h[f.newlane - 1];
                var lv = { t: f.newlane, a: lr ? this._ci(lr.CI) : '—', p: pre ? this._ci(pre.CI) : '—', b: this._ci(last.CI), k0: SMModel.M.K0, k: last.K, d: this._usdM(0.012 * ds.bonds) };
                if (!lr) { ins.push(this._t('ins_lane_late', lv)); }
                else if (pre && last.CI >= pre.CI) { ins.push(this._t('ins_lane', lv)); }
                else if (last.chIn > 0) { ins.push(this._t('ins_lane_priced', lv)); }
                else { ins.push(this._t('ins_lane_open', lv)); }
            } else if (f.lanes.length) {
                ins.push(this._t('ins_junctions', { n: f.lanes.length, d: this._usdM(0.012 * ds.bonds) }));
            }
            if (f.brt >= 2) { ins.push(this._t('ins_brt', { n: f.brt, o: this._usdM(ds.obligation), m: this._pct(last.modal) })); }
            if (f.forced) { ins.push(this._t('ins_forced', { t: f.forced })); }
            if (f.suspend) { ins.push(this._t('ins_suspend', { a: this._ci(h[3] ? h[3].CI : last.CI), b: this._ci(last.CI), o: this._ci(last.CI5) })); }
            if (f.halve) { ins.push(this._t('ins_halve', { c: this._usd(last.chIn) })); }
            if (f.rebate) { ins.push(this._t('ins_rebate')); }
            if (f.city) { ins.push(this._t('ins_city', { d: this._pct(100 * last.D) })); }
            if (f.noAlt && !f.forced) { ins.push(this._t('ins_noalt', { t: f.noAlt, c: this._usd(h[f.noAlt - 1].chIn) })); }
            if (f.over > 0.5) { ins.push(this._t('ins_over', { o: this._usdM(f.over) })); }
            if (f.single) { ins.push(this._t('ins_single')); }
            if (f.dismiss) { ins.push(this._t('ins_dismiss')); }
            if (f.oneoff) { ins.push(this._t('ins_oneoff', { o: this._ci(last.CI5) })); }
            if (f.order) { ins.push(this._t('ins_order')); }
            /* what the system did */
            if (!f.newlane && !f.lanes.length) { ins.push(this._t('ins_nolane', { k0: SMModel.M.K0, k: last.K })); }
            if (last.D >= 0.25 && !f.city) { ins.push(this._t('ins_density', { a: this._pct(15), b: this._pct(100 * last.D) })); }
            if (f.charge > 0 && last.chIn > 0 && ds.revUse === 'transit_housing' && !f.suspend && !f.forced) { ins.push(this._t('ins_charge', { c: this._usd(last.chIn), m0: this._pct(SMModel.M.MODAL0), m: this._pct(last.modal) })); }
            if (f.confirm && f.integrated && last.CI5 <= 1.55) { ins.push(this._t('ins_embedded', { o: this._ci(last.CI5) })); }
            ins.push(this._t('ins_numbers', { ci: this._ci(last.CI), aq: this._pct(last.AQ), p: this._num(last.P, 0), pm: this._num(ds.Pmin, 0), f: SMModel.M.FLOOR }));
            ins = ins.slice(0, 5);
            /* questions for class, from the case's own debrief prompts */
            if (f.suspend || f.halve || f.forced) { qs.push(this._t('q_threshold_rev', { p: this._num(h[3] ? h[3].P : last.P, 0) })); }
            else { qs.push(this._t('q_threshold', { pm: this._num(ds.Pmin, 0) })); }
            qs.push(f.newlane || f.lanes.length ? this._t('q_lane', { k: last.K }) : this._t('q_memo'));
            qs.push(this._t('q_opening', { ci: this._ci(last.CI), o: this._ci(last.CI5) }));
            return { insights: ins, turning: turning, questions: qs };
        }

        _debriefHTML(ds, summary) {
            var h = ds.hist || [];
            if (!h.length) { return ''; }
            var last = h[h.length - 1], perf = ds.performance || {}, s = perf.overallScore || 0, tier = perf.tier || SMModel.tier(s);
            var a = this._analyse(ds);
            var floorOk = last.P >= SMModel.M.FLOOR, ciOk = last.CI <= SMModel.M.CI_T + 0.005, aqOk = last.AQ <= SMModel.M.AQ_T;
            var k = function (label, val) { return '<div class="sm-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var rule = function (ok, txt) { return '<li class="' + (ok ? 'is-ok' : 'is-no') + '">' + (ok ? '✓ ' : '✗ ') + txt + '</li>'; };
            return '<div class="sm-debrief-head">'
                + '<p class="sm-kicker">' + this._t('d_kicker') + '</p>'
                + '<h2 class="sm-h2" id="smDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="sm-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="sm-chip sm-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="sm-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="sm-dkpis">'
                + k(this._t('kpi_ci'), this._ci(last.CI)) + k(this._t('kpi_aq'), this._pct(last.AQ)) + k(this._t('kpi_p'), this._num(last.P, 0))
                + k(this._t('d_k_modal'), this._pct(last.modal)) + k(this._t('d_k_cars'), this._num(last.K, 0)) + k(this._t('d_k_ci5'), this._ci(last.CI5)) + '</div>'
                + '<ul class="sm-rules">'
                + rule(ciOk, this._t('d_rule_ci', { v: this._ci(last.CI) })) + rule(aqOk, this._t('d_rule_aq', { v: this._pct(last.AQ) }))
                + rule(floorOk, this._t('d_rule_p', { v: this._num(last.P, 0), f: SMModel.M.FLOOR })) + '</ul>'
                + (perf.gate ? '<p class="sm-gate">' + this._t('d_gate', { f: SMModel.M.FLOOR }) + '</p>' : '')
                + '<h3>' + this._t('d_turning') + '</h3><p class="sm-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="sm-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="sm-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || SM_R;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            SM_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var hnd = function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); var v = self._el('smValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', hnd);
                el.addEventListener('change', hnd);
            });
            var relang = function () { try { self._paintOptions(); self._render(); self._relabelCharts(); } catch (e) {} };
            document.addEventListener('express:langchanged', relang);
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', relang);
                f.eventBus.on('period:submitted', function () {
                    try { self._paintOptions(); self._syncControls(); self._render(); } catch (e) {}
                    /* the guard blanks the round's choices just after the round changes (rule 13): repaint what reads them */
                    setTimeout(function () { try { self._paintHints(); self._paintPreview(); } catch (e) {} }, 60);
                });
                f.eventBus.on('period:undone', function () { try { self._paintOptions(); self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._paintOptions(); self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        /* Each round the three choice lists are rebuilt in the current language: the round's call has its own options,
           and the lane and zoning lists are renewed so their order carries no answer from one round to the next. */
        _fill(id, values, prefix, keep) {
            var el = this._el(id);
            if (!el) { return; }
            var cur = keep !== undefined ? keep : el.value;
            var want = values.join('|') + '#' + this._lang() + '#' + this._round();
            if (el.getAttribute('data-sm-fill') === want) { return; }
            var html = '<option value="">' + this._t('choose') + '</option>';
            for (var i = 0; i < values.length; i++) { html += '<option value="' + values[i] + '">' + this._t(prefix + values[i]) + '</option>'; }
            el.innerHTML = html;
            el.setAttribute('data-sm-fill', want);
            if (cur && values.indexOf(cur) >= 0) { el.value = cur; } else { el.value = ''; }
        }

        _paintOptions() {
            var st = this._state();
            if (!st) { return; }
            var t = this._round();
            var ds = st.domainState || {};
            var rd = this._el('readingInput');
            var same = rd && rd.getAttribute('data-sm-fill') && rd.getAttribute('data-sm-fill').split('#')[2] === String(t);
            this._fill('readingInput', SMModel.READ[t], 'r' + t + '_', same ? undefined : '');
            this._fill('laneInput', SMModel.LANES, 'lane_', undefined);
            this._fill('zoningInput', SMModel.ZONES, 'zone_', undefined);
        }

        /* On resume, undo or a new round the sliders show the player’s own last choices, not the authored defaults. */
        _syncControls() {
            var st = this._state();
            if (!st) { return; }
            var d = st.decisions || {};
            var put = function (id, v) { var el = document.getElementById(id); if (el && v !== undefined && v !== null && v !== '' && isFinite(Number(v))) { el.value = String(v); } };
            put('chargeInput', d.charge); put('transitInput', d.transit); put('commsInput', d.comms);
            this._paintOutputs();
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var t = over ? (st.history ? st.history.length : SM_R) : this._round();
            this._paintStatic(t, over);
            this._paintSteps(t, over);
            this._paintBriefing(t, over);
            this._paintKpis(ds);
            this._paintMap(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintHints();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('smForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic(t, over) {
            var terms = ['cld', 'reinforcing', 'balancing', 'induced', 'leverage', 'charge', 'upzoning', 'burden', 'worse', 'durability', 'ci', 'who'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('smGlossary', html);
            var tt = Math.min(t, SM_R);
            this._set('smCallLegend', this._t('call_legend', { t: tt }));
            var lab = this._el('readingLabel');
            if (lab) { var l = this._t('call_label_' + tt); if (lab.textContent !== l) { lab.textContent = l; } }
            var st = this._state(), ds = (st && st.domainState) || {};
            this._set('smSpendLegend', this._t('group_spend', { e: this._usdM(ds.envLeft) }));
            var sc = function (a, b) { return '<span>' + a + '</span><span>' + b + '</span>'; };
            this._set('chargeScale', sc(this._t('charge_none'), this._usd(SMModel.M.CH_MAX)));
            this._set('transitScale', sc('0', this._usdM(SMModel.M.TR_MAX, 0)));
            this._set('commsScale', sc('0', this._usdM(SMModel.M.CO_MAX, 0)));
        }

        _paintSteps(t, over) {
            var html = '';
            for (var i = 1; i <= SM_R; i++) {
                var cls = (i < t || (over && i <= t)) ? 'is-done' : (i === t ? 'is-now' : '');
                html += '<li class="' + cls + '"><span>' + this._t('rshort', { t: i }) + '</span></li>';
            }
            this._set('smSteps', html);
            var c = this._el('smCal');
            if (c) { c.textContent = over ? this._t('run_complete') : this._t('cal_' + t); }
        }

        _paintBriefing(t, over) {
            var ds = (this._state() || {}).domainState || {};
            var h = ds.hist || [];
            this._set('smTag', over ? this._t('tag_done') : this._t('tag_' + t));
            this._set('smBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + t));
            this._set('briefingText', over ? this._t('brief_done') : this._t('brief_' + t));
            var sig = [];
            if (!over) {
                var firstCharge = null;
                for (var i = 0; i < h.length; i++) { if (h[i].chIn > 0) { firstCharge = h[i]; break; } }
                if (firstCharge && t >= 2) { sig.push(this._t('sig_dil', { p: this._pct(100 * ds.dil) })); }
                if (ds.zEver && t >= 2) { sig.push(this._t(ds.zResisted ? 'sig_zone_no' : 'sig_zone_ok')); }
                if (t === 3) { sig.push(this._t(ds.strike ? 'sig_strike' : 'sig_nostrike')); if (ds.order) { sig.push(this._t('sig_order')); } }
                if (t === 4) {
                    var prev = h[h.length - 1];
                    var pressured = prev && (prev.works > 0.3 || prev.chIn > 0 || ds.works > 0.3);
                    sig.push(this._t(pressured ? 'sig_dip' : 'sig_nodip'));
                }
                if (t === 5) { sig.push(this._t('sig_tech')); }
                if (ds.suspended && t >= 2) { sig.push(this._t(ds.forcedAt ? 'sig_forced' : 'sig_suspended')); }
            }
            var s = this._el('smSignal');
            if (s) { var html = sig.join('<br>'); if (s.innerHTML !== html) { s.innerHTML = html; } s.hidden = !html; }
        }

        _delta(cur, prev, dec, good, unit) {
            if (prev == null) { return ''; }
            var d = cur - prev;
            if (Math.abs(d) < Math.pow(10, -(dec || 0)) / 2) { return '<span class="sm-flat">± 0</span> '; }
            var ok = good === 'down' ? d < 0 : d > 0;
            return '<span class="' + (ok ? 'sm-up' : 'sm-down') + '">' + (d > 0 ? '▲ ' : '▼ ') + this._sign(d, dec, unit || '').replace(/^[+−]/, '') + '</span> ';
        }

        _paintKpis(ds) {
            var h = ds.hist || [], last = h[h.length - 1], prev = h[h.length - 2];
            var M = SMModel.M;
            var t = h.length;
            this._set('ciDisplay', this._ci(ds.CI));
            this._set('ciSub', last ? this._delta(last.CI, prev ? prev.CI : M.CI0, 2, 'down') + this._t('ci_sub', { p: this._ci(SMModel.pathCI(t)), g: this._ci(M.CI_T) }) : this._t('ci_sub0', { g: this._ci(M.CI_T) }));
            this._set('aqDisplay', this._pct(ds.AQ));
            this._set('aqSub', last ? this._delta(last.AQ, prev ? prev.AQ : M.AQ0, 0, 'down', '') + this._t('aq_sub', { m: this._pct(last.modal) }) : this._t('aq_sub0', { m: this._pct(M.MODAL0) }));
            this._set('pDisplay', this._num(ds.P, 0));
            this._set('pSub', last ? this._delta(last.P, prev ? prev.P : M.P0, 0, 'up') + this._t('p_sub', { f: M.FLOOR, m: this._num(ds.Pmin, 0) }) : this._t('p_sub0', { f: M.FLOOR }));
            this._set('envDisplay', this._usdM(ds.envLeft));
            this._set('envSub', last ? this._t('env_sub', { o: this._usdM(ds.obligation + 0.012 * ds.bonds), r: this._usdM(last.rev) }) : this._t('env_sub0'));
            var ev = this._el('envDisplay'); if (ev) { ev.classList.toggle('is-neg', ds.envLeft < 0); }
            var pv = this._el('pDisplay'); if (pv) { pv.classList.toggle('is-neg', ds.P < M.FLOOR); }
