        _paintScore(ds) {
            var h = ds.hist || [];
            var el = this._el('smScoreCard');
            if (!el) { return; }
            if (!h.length) { this._set('smScoreCard', '<p class="sm-h3">' + this._t('score_title') + '</p><p class="sm-muted">' + this._t('score_empty') + '</p>'); return; }
            var p = ds.performance || {};
            var bar = function (label, v, cls) { var w = Math.round(100 * Math.max(0, Math.min(1, v))); return '<div class="sm-bar"><span class="sm-bar-l">' + label + '</span><span class="sm-bar-t"><span class="sm-bar-f ' + cls + '" style="width:' + w + '%"></span></span><span class="sm-bar-v">' + w + '</span></div>'; };
            var html = '<div class="sm-score-head"><span class="sm-h3">' + this._t('score_title') + '</span><span class="sm-score-n"><strong>' + p.overallScore + '</strong><small>/100</small></span>'
                + '<span class="sm-chip sm-chip-' + p.tier + '">' + this._t('perf_' + p.tier) + '</span></div>'
                + bar(this._t('sb_ci'), p.congestion, 'f1') + bar(this._t('sb_aq'), p.air, 'f2') + bar(this._t('sb_p'), p.durability, 'f3')
                + bar(this._t('sb_ol'), p.outlook, 'f4') + bar(this._t('sb_disc'), (p.process || 0) / 100, 'f5')
                + '<p class="sm-note">' + this._t('score_note') + '</p>';
