        _paintResult(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('smResultPanel', '<p class="sm-h3">' + this._t('res_title0') + '</p><p class="sm-muted">' + this._t('res_empty') + '</p>'); return; }
            var r = h[h.length - 1], prev = h[h.length - 2];
            var M = SMModel.M;
            var li = [];
            li.push(this._t('res_ci', { a: this._ci(prev ? prev.CI : M.CI0), b: this._ci(r.CI), c: this._usd(r.chIn), e: this._usd(r.chEff), m: this._pct(r.modal) }));
            li.push(this._t('res_cars', { a: prev ? prev.K : M.K0, b: r.K }));
            if (r.works > 0.05) { li.push(this._t('res_works', { w: this._pct(3.5 * Math.min(1.2, r.works), 1) })); }
            if (prev && prev.lane === 'newlane') { li.push(this._t('res_laneopen')); }
            if (r.strike) { li.push(this._t('res_strike')); }
            var parts = r.parts, names = { relief: 'pp_relief', comms: 'pp_comms', charge: 'pp_charge', zone: 'pp_zone', rev: 'pp_rev', lane: 'pp_lane', over: 'pp_over', read: 'pp_read', strike: 'pp_strike', dip: 'pp_dip', emb: 'pp_emb', order: 'pp_order' };
            var arr = [];
            for (var k in parts) { if (parts.hasOwnProperty(k) && Math.abs(parts[k]) >= 0.5) { arr.push([k, parts[k]]); } }
            arr.sort(function (a, b) { return Math.abs(b[1]) - Math.abs(a[1]); });
            var self = this;
            var pp = arr.slice(0, 4).map(function (x) { return self._t(names[x[0]]) + ' ' + self._sign(x[1], 1); }).join(' · ');
            li.push(this._t('res_p', { a: this._num(prev ? prev.P : M.P0, 0), b: this._num(r.P, 0), parts: pp || '—' }));
            if (r.forced) { li.push('<strong>' + this._t('res_forced') + '</strong>'); }
            li.push(this._t('res_money', { c: this._usdM(r.cost), r: this._usdM(r.rev), e: this._usdM(r.envLeft) }) + (r.over > 0 ? ' <strong>' + this._t('res_over', { o: this._usdM(r.over) }) + '</strong>' : ''));
            this._set('smResultPanel', '<p class="sm-h3">' + this._t('res_title', { t: r.t }) + '</p><ul class="sm-res">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var c = this._el('chargeInput'), tr = this._el('transitInput'), co = this._el('commsInput');
            if (c) { this._set('chargeOut', Number(c.value) > 0 ? this._usd(Number(c.value)) + this._t('per_day') : this._t('charge_none')); }
            if (tr) { this._set('transitOut', this._usdM(Number(tr.value))); }
            if (co) { this._set('commsOut', this._usdM(Number(co.value), 2)); }
        }

        _paintHints() {
            var r = this._read(), t = this._round();
            var st = this._state(), ds = (st && st.domainState) || {};
            this._set('readingHint', r.reading ? this._t('h_r' + t + '_' + r.reading) : this._t('h_r' + t));
            this._set('laneHint', r.lane ? this._t('h_lane_' + r.lane) : this._t('h_lane'));
            this._set('zoningHint', r.zoning ? this._t('h_zone_' + r.zoning) : this._t('h_zone'));
            var ch = isFinite(r.charge) ? r.charge : 0;
            this._set('chargeHint', ch > 0 ? this._t('h_charge_on', { r: this._usdM(ch * SMModel.M.REV_PER_USD * (ds.dil || 1)) }) : this._t('h_charge_off'));
            var tv = isFinite(r.transit) ? r.transit : 0;
            this._set('transitHint', this._t('h_transit', { o: this._usdM(0.2 * tv, 1) }));
            this._set('commsHint', this._t('h_comms'));
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState || this._runOver(st)) { this._set('smPreview', ''); return; }
            var ds = st.domainState, t = this._round(), r = this._read();
            /* every round starts blank (guard rule 13): until a choice is made the forecast assumes the neutral one */
            var neutral = { 1: 'single', 2: 'general', 3: 'partial', 4: 'hold', 5: 'phased' };
            var d = { reading: r.reading || neutral[t], lane: r.lane || 'none', zoning: r.zoning || ds.zoning || 'none',
                charge: isFinite(r.charge) ? r.charge : 0, transit: isFinite(r.transit) ? r.transit : 0, comms: isFinite(r.comms) ? r.comms : 0 };
            var fc;
            try { fc = SMModel.teamForecast(ds, d, t); } catch (e) { fc = null; }
            if (!fc) { this._set('smPreview', ''); return; }
            var cell = function (l, v, cls) { return '<div class="sm-pv' + (cls ? ' ' + cls : '') + '"><span>' + l + '</span><strong>' + v + '</strong></div>'; };
            var mapKey = fc.view;
            var html = '<div class="sm-pv-grid">'
                + cell(this._t('pv_cost'), this._usdM(fc.cost))
                + cell(this._t('pv_env'), this._usdM(fc.envLeft), fc.envLeft < 0 ? 'is-neg' : '')
                + cell(this._t('pv_ci_' + mapKey), this._ci(fc.CI))
                + cell(this._t('pv_ci5'), fc.CI5 == null ? this._t('pv_unmapped') : this._ci(fc.CI5), fc.CI5 == null ? 'is-muted' : '')
                + '</div><p class="sm-pv-note">' + this._t('pv_note_' + mapKey) + (!r.reading || !r.lane || !r.zoning ? ' ' + this._t('pv_blank') : '') + (fc.over > 0 ? ' <strong>' + this._t('pv_over', { o: this._usdM(fc.over) }) + '</strong>' : '') + '</p>';
            this._set('smPreview', html);
        }

        /* The causal-loop map: what the team drew in round 1, with each link drawn as strong as it ran last round. */
        _paintMap(ds) {
            var h = ds.hist || [], last = h[h.length - 1];
            var q = ds.mapQ;
            var W2 = 74, H2 = 17;
            var nodes = {
                cap: { x: 86, y: 34, k: 'n_cap', lv: 1 }, ci: { x: 265, y: 34, k: 'n_ci', lv: 0 }, chg: { x: 444, y: 34, k: 'n_chg', lv: 1 },
                car: { x: 86, y: 150, k: 'n_car', lv: 0.5 }, tq: { x: 265, y: 150, k: 'n_tq', lv: 0.5 }, pol: { x: 444, y: 150, k: 'n_pol', lv: 1 },
                em: { x: 86, y: 266, k: 'n_em', lv: 1 }, den: { x: 265, y: 266, k: 'n_den', lv: 1 }
            };
            var seen = function (n) { if (n.lv === 0) { return true; } if (q < 0) { return false; } return q >= n.lv; };
            var levers = { cap: true, chg: true, den: true };
            var prevK = h[h.length - 2] ? h[h.length - 2].K : SMModel.M.K0;
            var g = last ? {
                induced: Math.min(1, Math.max(0, (last.K - prevK) / 8)), charge: Math.min(1, last.chEff / 6), transit: Math.min(1, (last.Tq - 1) / 1.2),
                dens: Math.min(1, (last.D - 0.15) / 0.25), pol: Math.min(1, Math.abs(last.parts.charge) / 12), cap: Math.min(1, (last.C - 1) / 0.2),
                cong: Math.min(1, Math.max(0, (last.CI - 1) / 1.2))
            } : { induced: 0.3, charge: 0, transit: 0, dens: 0, pol: 0, cap: 0, cong: 0.6 };
            /* from, to, polarity, strength, bend */
            var edges = [
                ['cap', 'ci', '−', g.cap, 0], ['chg', 'ci', '−', g.charge, 0], ['ci', 'car', '−', g.induced, -18], ['car', 'ci', '+', g.cong, -18],
                ['ci', 'tq', '−', g.cong * 0.6, 0], ['tq', 'car', '−', g.transit, 0], ['den', 'tq', '+', g.dens, 0], ['den', 'car', '−', g.dens, 0],
                ['car', 'em', '+', g.cong * 0.7, 0], ['chg', 'pol', '−', g.pol, -18], ['pol', 'chg', '+', g.pol, -18], ['ci', 'pol', '−', g.cong * 0.5, 0]
            ];
            var clip = function (a, b) {
                var dx = b.x - a.x, dy = b.y - a.y;
                var t = Math.min(dx ? (W2 + 4) / Math.abs(dx) : 9, dy ? (H2 + 4) / Math.abs(dy) : 9);
                return { x: a.x + dx * t, y: a.y + dy * t };
            };
            var svg = '<svg viewBox="0 0 530 300" class="sm-cld" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">'
                + '<defs><marker id="smArr" viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="11" markerHeight="11" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#3b4062"/></marker></defs>';
            for (var i = 0; i < edges.length; i++) {
                var e = edges[i], A = nodes[e[0]], B = nodes[e[1]];
                if (!seen(A) || !seen(B)) { continue; }
                var p1 = clip(A, B), p2 = clip(B, A);
                var dx = p2.x - p1.x, dy = p2.y - p1.y, len = Math.sqrt(dx * dx + dy * dy) || 1;
                var bend = e[4];
                var mx = (p1.x + p2.x) / 2 + (dy / len) * bend, my = (p1.y + p2.y) / 2 - (dx / len) * bend;
                var w = 1.4 + 3.6 * Math.max(0, Math.min(1, e[3]));
                svg += '<path d="M' + p1.x.toFixed(1) + ',' + p1.y.toFixed(1) + ' Q' + mx.toFixed(1) + ',' + my.toFixed(1) + ' ' + p2.x.toFixed(1) + ',' + p2.y.toFixed(1) + '" class="sm-edge" stroke-width="' + w.toFixed(1) + '" marker-end="url(#smArr)"/>';
                var lx = 0.15 * p1.x + 0.5 * mx + 0.35 * p2.x, ly = 0.15 * p1.y + 0.5 * my + 0.35 * p2.y;
                var ox = Math.abs(dx) > Math.abs(dy) ? 0 : 9, oy = Math.abs(dx) > Math.abs(dy) ? -6 : 4;
                svg += '<text x="' + (lx + ox).toFixed(1) + '" y="' + (ly + oy).toFixed(1) + '" class="sm-pol">' + e[2] + '</text>';
            }
            for (var key in nodes) {
                if (!nodes.hasOwnProperty(key)) { continue; }
                var n = nodes[key], vis = seen(n);
                svg += '<g class="sm-node' + (vis ? '' : ' is-off') + (levers[key] ? ' is-lever' : '') + '"><rect x="' + (n.x - W2) + '" y="' + (n.y - H2) + '" width="' + (2 * W2) + '" height="' + (2 * H2) + '" rx="9"/>'
                    + '<text x="' + n.x + '" y="' + (n.y + 4.5) + '" text-anchor="middle">' + (vis ? this._t(n.k) : '?') + '</text></g>';
            }
            if (q >= 0.5) { svg += '<text x="128" y="96" class="sm-loop sm-loop-b">B1</text><text x="205" y="112" class="sm-loop sm-loop-r">R1</text>'; }
            if (q >= 1) { svg += '<text x="398" y="96" class="sm-loop sm-loop-b">B2</text>'; }
            svg += '</svg>';
            this._set('smMap', svg);
            var note = q < 0 ? this._t('map_note_none') : this._t('map_note_' + (q >= 1 ? 'six' : (q === 0.5 ? 'three' : 'single')));
            this._set('smMapNote', note);
            this._set('smMapLegend', q >= 1 ? this._t('map_legend_six') : (q === 0.5 ? this._t('map_legend_three') : this._t('map_legend_min')));
            var alt = this._t('map_alt', { n: note });
            if (last) { alt += ' ' + this._t('map_alt_run', { k: this._num(last.K, 0), c: this._usd(last.chEff), d: this._pct(100 * last.D), q: this._num(last.Tq, 2) }); }
            this._set('smMapAlt', alt);
        }

