        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new SystemsMapAdapter(), {
            simulationType: 'systemsmap_causal_loops',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
